const data = $('Code in JavaScript1').first().json;


// ─────────────────────────────────────
// DATE FORMATTER — Australian DD/MM/YY
// ─────────────────────────────────────

function toAusDate(value) {
  if (!value || value === 'TBC') return 'TBC';

  const date = new Date(value);

  // If it parsed as a valid date
  if (!isNaN(date.getTime())) {
    const dd = String(date.getUTCDate()).padStart(2, '0');
    const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
    const yy = String(date.getUTCFullYear()).slice(-2);
    return `${dd}/${mm}/${yy}`;
  }

  // If partial like "August" or "August 2024" — return as-is
  return value;
}

// ─────────────────────────────────────
// HELPERS
// ─────────────────────────────────────

function formatDeliverableHeadlines(deliverables) {
  if (!Array.isArray(deliverables) || deliverables.length === 0) {
    return 'TBC';
  }

  return deliverables
    .map(entry => entry.deliverable || 'TBC')
    .join('\n');
}

function formatSpecs(deliverables) {

  if (!Array.isArray(deliverables) || deliverables.length === 0) {
    return 'TBC';
  }

  return deliverables.map(entry => {

    if (!Array.isArray(entry.specs) || entry.specs.length === 0) {
      return 'TBC';
    }

    return entry.specs.map(spec => {

      const categoryLine = [
        spec.category,
        spec.scenarios ? `${spec.scenarios}` : null,
        spec.copy_rule ? `(${spec.copy_rule})` : null
      ]
      .filter(Boolean)
      .join(' — ');

      const items = Array.isArray(spec.items)
        ? spec.items.map(item => {

            const notePart =
              item.notes &&
              item.notes !== item.label
                ? ` — ${item.notes}`
                : '';

            return `    • ${item.size}  ${item.label}${notePart}`;

          }).join('\n')
        : '';

      return `${categoryLine}\n${items}`;

    }).join('\n\n');

  }).join('\n\n');
}

function formatReferences(references) {

  if (!Array.isArray(references) || references.length === 0) {
    return 'TBC';
  }

  return references
    .map(r => `• ${r.heading}\n  ${r.description}`)
    .join('\n\n');
}

function formatBudget(budget) {

  if (
    !budget ||
    typeof budget !== 'object'
  ) {
    return 'Not Available. Budget Need to be confirmed';
  }

  // New simplified structure
  if (budget.notes) {
    return budget.notes;
  }

  // Backward compatibility
  const media = budget.media || {};
  const production = budget.production || {};

  const sections = [];

  if (
    media.min ||
    media.max ||
    media.currency
  ) {
    sections.push(
      `Media Budget: ${val(media.currency)} ${val(media.min)} - ${val(media.max)}`
    );
  }

  if (
    production.min ||
    production.max ||
    production.currency
  ) {
    sections.push(
      `Production Budget: ${val(production.currency)} ${val(production.min)} - ${val(production.max)}`
    );
  }

  if (budget.notes) {
    sections.push(budget.notes);
  }

  return sections.length
    ? sections.join('\n')
    : 'Not Available. Budget Need to be confirmed';
}

function bulletList(arr) {

  if (!Array.isArray(arr) || arr.length === 0) {
    return 'TBC';
  }

  return arr
    .map(i => `• ${i}`)
    .join('\n');
}

function val(value) {

  return (
    value !== undefined &&
    value !== null &&
    value !== ''
  )
    ? value
    : 'TBC';
}

// ─────────────────────────────────────
// REPLACEMENTS
// ─────────────────────────────────────

const replacements = [

  // ── DETAILS ──
  ["{{client_name}}",     val(data.details?.client_name)],
  ["{{job_number}}",      val(data.details?.job_number)],
  ["{{description}}",     val(data.details?.description)],
  ["{{allocated_hours}}", val(data.details?.allocated_hours)],
  ["{{account_lead}}",    val(data.details?.account_lead)],

  // ── TIMINGS ──
  ["{{client_brief_received}}",
    toAusDate(data.timings?.client_brief_received)
  ],

  ["{{brief_date}}",
    toAusDate(data.timings?.design_brief_date)
  ],

  ["{{internal_review}}",
    toAusDate(data.timings?.internal_review)
  ],

  ["{{client_review}}",
    toAusDate(data.timings?.client_review)
  ],

  ["{{material_deadline}}",
    toAusDate(data.timings?.material_deadline)
  ],

  // ── SECTIONS ──
  ["{{background}}",
    val(data.sections?.background)
  ],

  ["{{proposition}}",
    val(data.sections?.proposition)
  ],

  ["{{task}}",
    data.sections?.task
      ? val(data.sections.task.main) +
        '\n\n' +
        bulletList(data.sections.task.goals)
      : 'TBC'
  ],

  ["{{deliverables}}",
    formatDeliverableHeadlines(data.sections?.deliverables)
  ],

  ["{{specs}}",
    formatSpecs(data.sections?.deliverables)
  ],

  ["{{mandatories}}",
    bulletList(data.sections?.mandatories)
  ],

  ["{{budget}}",
    formatBudget(data.sections?.budget)
  ],

  ["{{references}}",
    formatReferences(data.sections?.references)
  ]

];

// ─────────────────────────────────────
// RETURN
// ─────────────────────────────────────

return replacements.map(([search, replace]) => ({
  json: {
    search,
    replace
  }
}));

// ======================================
// Get Raw AI Response
// ======================================

const input = $input.first().json;

let rawText =
  input.content?.[0]?.text ||
  input.text ||
  '';

if (!rawText) {
  throw new Error(
    'No text content found from AI response'
  );
}

// ======================================
// Remove Markdown Wrappers
// ======================================

rawText = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

// ======================================
// Extract JSON Only
// (handles extra text before/after JSON)
// ======================================

const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

if (
  firstBrace !== -1 &&
  lastBrace !== -1 &&
  lastBrace > firstBrace
) {
  rawText =
    rawText.substring(
      firstBrace,
      lastBrace + 1
    );
}

// ======================================
// Fix Truncated JSON Safely
// ======================================

const fixJson = (text) => {

  const openBraces =
    (text.match(/{/g) || []).length;

  const closeBraces =
    (text.match(/}/g) || []).length;

  const openBrackets =
    (text.match(/\[/g) || []).length;

  const closeBrackets =
    (text.match(/\]/g) || []).length;

  const missingBraces =
    Math.max(
      0,
      openBraces - closeBraces
    );

  const missingBrackets =
    Math.max(
      0,
      openBrackets - closeBrackets
    );

  return (
    text +
    '}'.repeat(missingBraces) +
    ']'.repeat(missingBrackets)
  );
};

rawText = fixJson(rawText);

// ======================================
// Parse JSON
// ======================================

try {

  const parsed =
    JSON.parse(rawText);

  // ======================================
// Always set client_brief_received
// to today's date (YYYY-MM-DD)
// ======================================

   const today = new Date().toLocaleDateString('en-CA');

  if (!parsed.timings) {
     parsed.timings = {};
  }

  parsed.timings.client_brief_received = today;

  return [{
    json: parsed
  }];

} catch (err) {

  return [{
    json: {
      error: true,
      message: err.message,
      raw_output: rawText
    }
  }];
}
